import { defineConfig } from 'vite'
import { tanstackStart } from '@tanstack/react-start/plugin/vite'
import viteReact from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'
import { cloudflare } from '@cloudflare/vite-plugin'

import ssrRoutes from './src/site/ssr-routes.json' with { type: 'json' }

const isSsrOnly = (path: string) =>
  ssrRoutes.paths.some((p) => path === p || path.startsWith(`${p}/`))

// Files generated by routes; any other path with an extension is a file under
// public/ that the crawler found through a link (e.g. /fonts/OFL.txt).
const GENERATED_FILES = ['/sitemap.xml', '/robots.txt']
const isPublicFile = (path: string) => /\.[a-z0-9]+$/i.test(path) && !GENERATED_FILES.includes(path)

export default defineConfig({
  // Public build-time config lives in env/.env (committed; docs/PLAN.md §9.5-1).
  envDir: 'env',
  resolve: { tsconfigPaths: true },
  plugins: [
    cloudflare({ viteEnvironment: { name: 'ssr' } }),
    tailwindcss(),
    tanstackStart({
      prerender: {
        enabled: true,
        // Link crawling is on by default, so SSR-only pages linked from a
        // prerendered page would get frozen at build time without this filter.
        filter: (page) => !isSsrOnly(page.path) && !isPublicFile(page.path),
        // `/board` → board.html (no trailing slash), matching wrangler's
        // assets.html_handling = "auto-trailing-slash".
        autoSubfolderIndex: false,
        failOnError: true,
      },
      // Not linked from any page, so the crawler would not find them.
      pages: GENERATED_FILES.map((path) => ({ path })),
    }),
    viteReact(),
  ],
})
